const YT_IDLE_GIF = "data:image/gif;base64,";

const YT_ICONS = {
    youtube: ["path", '<path fill="#ff0033" d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.6 12 3.6 12 3.6s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2 31 31 0 0 0 0 12a31 31 0 0 0 .5 5.8 3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1A31 31 0 0 0 24 12a31 31 0 0 0-.5-5.8Z"/><path fill="#fff" d="m9.6 15.6 6.2-3.6-6.2-3.6v7.2Z"/>'],
    play: ["fill", '<path d="M7 4.5v15a1 1 0 0 0 1.5.86l12-7.5a1 1 0 0 0 0-1.72l-12-7.5A1 1 0 0 0 7 4.5Z"/>'],
    pause: ["fill", '<rect x="6" y="4.5" width="4" height="15" rx="1.2"/><rect x="14" y="4.5" width="4" height="15" rx="1.2"/>'],
    chevron: ["line", '<path d="m6 9 6 6 6-6"/>'],
    back: ["line", '<path d="m15 18-6-6 6-6"/>'],
    library: ["line", '<path d="m16 6 4 14"/><path d="M12 6v14"/><path d="M8 8v12"/><path d="M4 4v16"/>'],
    external: ["line", '<path d="M15 3h6v6"/><path d="M10 14 21 3"/><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>'],
    close: ["line", '<path d="M18 6 6 18"/><path d="m6 6 12 12"/>'],
    prev: ["fill", '<path d="M18.5 5.2v13.6a.8.8 0 0 1-1.25.66L8.6 12.66a.8.8 0 0 1 0-1.32l8.65-6.8a.8.8 0 0 1 1.25.66Z"/><rect x="4.5" y="5" width="2.6" height="14" rx="1.3"/>'],
    next: ["fill", '<path d="M5.5 5.2v13.6a.8.8 0 0 0 1.25.66l8.65-6.8a.8.8 0 0 0 0-1.32L6.75 4.54a.8.8 0 0 0-1.25.66Z"/><rect x="16.9" y="5" width="2.6" height="14" rx="1.3"/>'],
    volume: ["line", '<path d="M11 4.7a.7.7 0 0 0-1.2-.5L6.41 7.59A1.4 1.4 0 0 1 5.42 8H3a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2.42a1.4 1.4 0 0 1 .99.41l3.39 3.39a.7.7 0 0 0 1.2-.5z"/><path d="M16 9a5 5 0 0 1 0 6"/><path d="M19.36 18.36a9 9 0 0 0 0-12.73"/>'],
    volumeLow: ["line", '<path d="M11 4.7a.7.7 0 0 0-1.2-.5L6.41 7.59A1.4 1.4 0 0 1 5.42 8H3a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2.42a1.4 1.4 0 0 1 .99.41l3.39 3.39a.7.7 0 0 0 1.2-.5z"/><path d="M16 9a5 5 0 0 1 0 6"/>'],
    mute: ["line", '<path d="M11 4.7a.7.7 0 0 0-1.2-.5L6.41 7.59A1.4 1.4 0 0 1 5.42 8H3a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2.42a1.4 1.4 0 0 1 .99.41l3.39 3.39a.7.7 0 0 0 1.2-.5z"/><path d="m22 9-6 6"/><path d="m16 9 6 6"/>'],
    fullscreen: ["line", '<path d="M8 3H5a2 2 0 0 0-2 2v3"/><path d="M21 8V5a2 2 0 0 0-2-2h-3"/><path d="M3 16v3a2 2 0 0 0 2 2h3"/><path d="M16 21h3a2 2 0 0 0 2-2v-3"/>'],
    search: ["line", '<circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/>'],
};
const ytIcon = (name, size = 16) => {
    const [kind, inner] = YT_ICONS[name];
    const paint = kind === "fill" ? 'fill="currentColor" stroke="currentColor" stroke-width="1.5"'
        : kind === "line" ? 'fill="none" stroke="currentColor" stroke-width="2"' : "";
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" ${paint} stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${inner}</svg>`;
};

const parseYouTube = text => {
    let u;
    try { u = new URL(String(text).trim()); } catch { return null; }
    const host = u.hostname.replace(/^(www|m|music)\./, "");
    let id = null;
    if (host === "youtu.be") id = u.pathname.slice(1).split("/")[0];
    else if (host === "youtube.com" || host === "youtube-nocookie.com") {
        id = u.searchParams.get("v") || (/^\/(?:shorts|embed|live|v)\/([\w-]{11})/.exec(u.pathname) || [])[1] || null;
    } else return null;
    const list = u.searchParams.get("list");
    if (id && !/^[\w-]{11}$/.test(id)) id = null;
    if (!id && !list) return null;
    const t = u.searchParams.get("t") || u.searchParams.get("start") || "";
    const start = /^\d+$/.test(t) ? Number(t) : (() => {
        const m = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/.exec(t);
        return m ? (Number(m[1] || 0) * 3600 + Number(m[2] || 0) * 60 + Number(m[3] || 0)) : 0;
    })();
    return { id, list, start };
};

BThemer.definePlugin({
    id: "youtube",
    name: "YouTube",
    description: "Watch YouTube inside Discord: a player above your user panel with search, and links you paste play right there. Follow channels (settings) to see their latest videos. No sign-in needed.",
    author: "Be Themer",
    version: "1.0.0",
    settings: {
        followStatus: { type: "info", label: "Your channels", default: "Not following any channels yet" },
        followInput: { type: "text", label: "Channel to follow: paste a channel link or @handle, then press Follow", default: "" },
        followBtn: { type: "button", label: "Follow that channel", text: "Follow" },
        importBtn: {
            type: "button", label: "Import all your YouTube subscriptions", text: "Import…",
            description: "takeout.google.com → Deselect all → tick YouTube and YouTube Music → \"All YouTube data included\": only subscriptions → Export. Unzip it and pick subscriptions.csv here.",
        },
        unfollowAllBtn: { type: "button", label: "Unfollow every channel", text: "Unfollow all" },
        includeShorts: { type: "toggle", label: "Show Shorts in Subscriptions", default: false },
        showVideo: { type: "toggle", label: "Show the video (off = audio-only bar, keeps playing)", default: true },
        rememberLast: { type: "toggle", label: "Reopen the last video after restarting Discord", default: true },
    },
    css: `
        .bt-yt { position: relative; padding: 10px 10px 8px; border-bottom: 1px solid var(--background-modifier-accent, rgb(78 80 88 / .48));
            color: var(--text-normal, #dbdee1); font: 14px/1.25 var(--font-primary, "gg sans", sans-serif); }
        .bt-yt[hidden], .bt-yt [hidden] { display: none !important; }
        .bt-yt-head { display: flex; align-items: center; gap: 8px; min-width: 0; }
        .bt-yt-logo { flex: none; display: grid; place-items: center; }
        .bt-yt-title { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-weight: 600; font-size: 13px;
            color: var(--header-primary, #f2f3f5); }
        .bt-yt-title small { display: block; font-weight: 400; font-size: 11px; color: var(--text-muted, #949ba4); }
        .bt-yt .bt-yt-btn { display: grid; place-items: center; width: 28px; height: 28px; flex: none; padding: 0; border: 0;
            border-radius: 50% !important; background: none; color: var(--interactive-normal, #b5bac1); cursor: pointer; transition: background .12s, color .12s; }
        .bt-yt .bt-yt-btn:hover { background: var(--background-modifier-hover, rgb(78 80 88 / .3)); color: var(--interactive-hover, #dbdee1); }
        .bt-yt .bt-yt-btn.bt-yt-mini { display: none; background: #ff0033; color: #fff; }
        .bt-yt .bt-yt-btn.bt-yt-mini:hover { background: #ff3355; color: #fff; }
        .bt-yt-chevron svg { transition: transform .2s ease; transform: rotate(180deg); }
        .bt-yt-collapsed .bt-yt-chevron svg { transform: rotate(0deg); }
        .bt-yt-screen { position: relative; margin-top: 8px; width: 100%; aspect-ratio: 16 / 9; border-radius: 8px; overflow: hidden; background: #000; }
        .bt-yt-screen iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
        .bt-yt-empty { position: absolute; inset: 0; background: #fff; }
        .bt-yt-idle { display: block; width: 100%; height: 100%; object-fit: cover; pointer-events: none; user-select: none; }
        .bt-yt-audio .bt-yt-screen { height: 0; margin: 0; aspect-ratio: auto; }
        .bt-yt-controls { margin-top: 6px; }
        .bt-yt-ctlrow { display: flex; align-items: center; gap: 2px; min-width: 0; }
        .bt-yt .bt-yt-ctlrow .bt-yt-btn { width: 28px; height: 28px; }
        .bt-yt .bt-yt-ctlrow .bt-yt-play { background: #f2f3f5; color: #0f0f0f; margin: 0 2px; }
        .bt-yt .bt-yt-ctlrow .bt-yt-play:hover { background: #fff; color: #000; }
        .bt-yt-time { margin-left: 6px; font: 11px var(--font-code, Consolas, monospace); color: var(--text-muted, #949ba4); white-space: nowrap; font-variant-numeric: tabular-nums; }
        .bt-yt-grow { flex: 1; }
        .bt-yt-slider { position: relative; height: 14px; cursor: pointer; touch-action: none; flex: none; }
        .bt-yt-slider::before { content: ""; position: absolute; left: 0; right: 0; top: 5px; height: 4px; border-radius: 2px; background: rgb(255 255 255 / .16); }
        .bt-yt-fill { position: absolute; left: 0; top: 5px; height: 4px; border-radius: 2px; background: #ff0033; pointer-events: none; }
        .bt-yt-knob { position: absolute; top: 2px; width: 10px; height: 10px; margin-left: -5px; border-radius: 50%; background: #fff;
            box-shadow: 0 1px 3px rgb(0 0 0 / .4); opacity: 0; transition: opacity .1s; pointer-events: none; }
        .bt-yt-slider:hover .bt-yt-knob, .bt-yt-dragging .bt-yt-knob { opacity: 1; }
        .bt-yt-seek { width: 100%; }
        .bt-yt-vol { width: 64px; }
        .bt-yt-vol .bt-yt-fill { background: #f2f3f5; }
        .bt-yt-collapsed .bt-yt-controls { display: none !important; }
        .bt-yt-screen:fullscreen { border-radius: 0; }
        .bt-yt-searchbox { position: relative; margin-top: 8px; }
        .bt-yt-search { width: 100%; box-sizing: border-box; height: 30px; padding: 0 10px 0 30px; border: 1px solid transparent; border-radius: 999px; outline: none;
            background: var(--input-background, var(--background-tertiary, #1e1f22)); color: var(--text-normal, #dbdee1); font: 13px var(--font-primary, sans-serif); }
        .bt-yt-search:focus { border-color: #ff0033; }
        .bt-yt-search::placeholder { color: var(--text-muted, #949ba4); }
        .bt-yt-searchicon { position: absolute; left: 10px; top: 8px; color: var(--text-muted, #949ba4); pointer-events: none; }
        .bt-yt-list { margin-top: 6px; max-height: 250px; overflow-y: auto; scrollbar-width: thin; display: flex; flex-direction: column; gap: 2px; }
        .bt-yt-row { display: flex; gap: 8px; align-items: center; padding: 4px; border-radius: 6px; cursor: pointer; min-width: 0; }
        .bt-yt-row:hover, .bt-yt-row.bt-yt-sel { background: var(--background-modifier-hover, rgb(78 80 88 / .3)); }
        .bt-yt-thumb { position: relative; width: 80px; flex: none; aspect-ratio: 16 / 9; border-radius: 4px; background: #111 center / cover; }
        .bt-yt-dur { position: absolute; right: 2px; bottom: 2px; padding: 0 3px; border-radius: 3px; background: rgb(0 0 0 / .8); color: #fff; font: 600 10px/14px var(--font-primary, sans-serif); }
        .bt-yt-dur.bt-yt-live { background: #ff0033; }
        .bt-yt-rowtext { flex: 1; min-width: 0; }
        .bt-yt-rowtitle { font-size: 12px; font-weight: 600; color: var(--header-primary, #f2f3f5); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
        .bt-yt-rowchan { font-size: 11px; color: var(--text-muted, #949ba4); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .bt-yt-chanrow { padding: 6px 4px 6px 10px; }
        .bt-yt-backrow { gap: 6px; font-weight: 700; font-size: 12px; color: var(--header-primary, #f2f3f5); }
        .bt-yt-msg { padding: 14px 6px; text-align: center; color: var(--text-muted, #949ba4); font-size: 12px; }
        .bt-yt-tabs { display: flex; gap: 4px; flex-wrap: wrap; margin-top: 8px; }
        .bt-yt-tabs button { border: 0; padding: 4px 10px; border-radius: 999px; cursor: pointer; background: rgb(255 255 255 / .07);
            color: var(--text-normal, #dbdee1); font: 600 11px var(--font-primary, sans-serif); }
        .bt-yt-tabs button:hover { background: rgb(255 255 255 / .12); }
        .bt-yt-tabs button.bt-yt-on { background: #f2f3f5; color: #0f0f0f; }
        .bt-yt-progress { display: none; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: rgb(255 255 255 / .08); }
        .bt-yt-progress div { height: 100%; width: 0; background: #ff0033; transition: width .5s linear; }
        /* collapsed: one row */
        .bt-yt.bt-yt-collapsed { padding: 6px 8px 8px; }
        .bt-yt-collapsed .bt-yt-searchbox, .bt-yt-collapsed .bt-yt-list, .bt-yt-collapsed .bt-yt-tabs,
        .bt-yt-collapsed .bt-yt-head .bt-yt-btn:not(.bt-yt-chevron):not(.bt-yt-mini) { display: none !important; }
        .bt-yt-collapsed .bt-yt-screen { height: 0; margin: 0; aspect-ratio: auto; }
        .bt-yt.bt-yt-collapsed .bt-yt-btn.bt-yt-mini { display: grid; }
        .bt-yt-collapsed .bt-yt-progress { display: block; }
    `,

    start(api) {
        const el = api.el;
        let stopped = false;
        let channels = [];
        let current = null;
        let state = { playing: false, time: 0, duration: 0, at: 0, volume: 100, muted: false, inList: false };
        let collapsed = false;
        let view = "search";
        let feed = "subs";
        let openChannel = null;

        const root = el("div", { className: "bt-yt" });
        const btn = (name, title, onClick, extra = "") => {
            const b = el("button", { className: `bt-yt-btn ${extra}`.trim(), type: "button", title, innerHTML: ytIcon(name, 16) });
            b.setAttribute("aria-label", title);
            b.onclick = e => { e.stopPropagation(); onClick(e, b); };
            return b;
        };
        const logo = el("span", { className: "bt-yt-logo", innerHTML: ytIcon("youtube", 20) });
        const title = el("div", { className: "bt-yt-title" });
        const miniBtn = btn("play", "Play", () => togglePlay(), "bt-yt-mini");
        const libraryBtn = btn("library", "Subscriptions: latest videos from channels you follow", () => setView(view === "library" ? "search" : "library"));
        const openBtn = btn("external", "Open on YouTube", () => {
            if (!current) return;
            const url = current.id ? `https://www.youtube.com/watch?v=${current.id}${current.list ? `&list=${current.list}` : ""}&t=${Math.floor(liveTime())}s`
                : `https://www.youtube.com/playlist?list=${current.list}`;
            window.open(url, "_blank", "noopener");
        });
        const closeBtn = btn("close", "Stop and close the video", () => loadVideo(null));
        const chevronBtn = btn("chevron", "Collapse", () => setCollapsed(!collapsed), "bt-yt-chevron");
        const head = el("div", { className: "bt-yt-head" });
        head.append(logo, title, miniBtn, libraryBtn, openBtn, closeBtn, chevronBtn);

        const screen = el("div", { className: "bt-yt-screen" });
        const empty = el("div", { className: "bt-yt-empty" });
        empty.append(el("img", { className: "bt-yt-idle", src: YT_IDLE_GIF, alt: "", draggable: false }));
        screen.append(empty);
        let frame = null;

        let volDragging = false, volSetAt = 0, seekDragging = false;
        const fmt = sec => {
            sec = Math.max(0, Math.floor(sec || 0));
            const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), x = String(sec % 60).padStart(2, "0");
            return h ? `${h}:${String(m).padStart(2, "0")}:${x}` : `${m}:${x}`;
        };
        const slider = (cls, onInput, onDone) => {
            const bar = el("div", { className: `bt-yt-slider ${cls}` });
            const fill = el("div", { className: "bt-yt-fill" });
            const knob = el("div", { className: "bt-yt-knob" });
            bar.append(fill, knob);
            bar.set = f => { const pct = `${Math.max(0, Math.min(1, f)) * 100}%`; fill.style.width = pct; knob.style.left = pct; };
            bar.addEventListener("pointerdown", e => {
                e.preventDefault();
                bar.setPointerCapture(e.pointerId);
                bar.classList.add("bt-yt-dragging");
                const r = bar.getBoundingClientRect();
                const at = ev => Math.max(0, Math.min(1, (ev.clientX - r.left) / r.width));
                onInput(at(e), true);
                const move = ev => onInput(at(ev), true);
                bar.addEventListener("pointermove", move);
                bar.addEventListener("pointerup", ev => {
                    bar.removeEventListener("pointermove", move);
                    bar.classList.remove("bt-yt-dragging");
                    onDone(at(ev));
                }, { once: true });
            });
            return bar;
        };
        const seekBar = slider("bt-yt-seek", (f, dragging) => {
            seekDragging = dragging;
            seekBar.set(f);
            timeText.textContent = `${fmt(f * state.duration)} / ${fmt(state.duration)}`;
        }, f => {
            seekDragging = false;
            const sec = f * state.duration;
            post("seekTo", [sec, true]);
            state.time = sec; state.at = Date.now();
        });
        const setVolume = v => {
            v = Math.round(Math.max(0, Math.min(100, v)));
            state.volume = v; volSetAt = Date.now();
            post("setVolume", [v]);
            if (v > 0 && state.muted) { post("unMute"); state.muted = false; }
            renderControls();
        };
        const volBar = slider("bt-yt-vol", f => { volDragging = true; setVolume(f * 100); }, f => { volDragging = false; setVolume(f * 100); });
        volBar.addEventListener("wheel", e => { e.preventDefault(); setVolume(state.volume + (e.deltaY < 0 ? 5 : -5)); }, { passive: false });
        const ctlPrev = btn("prev", "Previous video", () => post("previousVideo"));
        const ctlPlay = btn("play", "Play", () => togglePlay(), "bt-yt-play");
        const ctlNext = btn("next", "Next video", () => post("nextVideo"));
        const timeText = el("span", { className: "bt-yt-time", textContent: "0:00 / 0:00" });
        const muteBtn = btn("volume", "Mute", () => {
            state.muted = !state.muted; volSetAt = Date.now();
            post(state.muted ? "mute" : "unMute");
            renderControls();
        });
        const fsBtn = btn("fullscreen", "Fullscreen", () => {
            if (document.fullscreenElement) document.exitFullscreen().catch(() => {});
            else screen.requestFullscreen?.().catch(() => {});
        });
        const ctlRow = el("div", { className: "bt-yt-ctlrow" });
        ctlRow.append(ctlPrev, ctlPlay, ctlNext, timeText, el("span", { className: "bt-yt-grow" }), muteBtn, volBar, fsBtn);
        const controls = el("div", { className: "bt-yt-controls" });
        controls.append(seekBar, ctlRow);
        function renderControls() {
            controls.hidden = !current;
            ctlPlay.innerHTML = ytIcon(state.playing ? "pause" : "play", 14);
            ctlPlay.title = state.playing ? "Pause" : "Play";
            ctlPrev.hidden = ctlNext.hidden = !state.inList;
            const v = state.muted ? 0 : state.volume;
            muteBtn.innerHTML = ytIcon(v <= 0 ? "mute" : v < 50 ? "volumeLow" : "volume", 16);
            muteBtn.title = state.muted ? "Unmute" : "Mute";
            if (!volDragging) volBar.set(v / 100);
            volBar.title = `Volume ${Math.round(v)}%`;
        }

        const searchBox = el("div", { className: "bt-yt-searchbox" });
        const searchIcon = el("span", { className: "bt-yt-searchicon", innerHTML: ytIcon("search", 14) });
        const input = el("input", { className: "bt-yt-search", type: "search", placeholder: "Search YouTube or paste a link", spellcheck: false });
        searchBox.append(searchIcon, input);
        const tabs = el("div", { className: "bt-yt-tabs" });
        const FEEDS = [["subs", "Subscriptions"], ["channels", "Channels"]];
        const tabBtns = FEEDS.map(([k, label]) => {
            const b = el("button", { type: "button", textContent: label });
            b.onclick = () => { feed = k; showFeed(); };
            tabs.append(b);
            return [k, b];
        });
        const list = el("div", { className: "bt-yt-list" });
        const progress = el("div", { className: "bt-yt-progress" });
        const progressFill = el("div");
        progress.append(progressFill);
        root.append(head, screen, controls, searchBox, tabs, list, progress);

        const post = (func, args = []) => {
            try { frame?.contentWindow?.postMessage(JSON.stringify({ event: "command", func, args }), "*"); } catch {}
        };
        const liveTime = () => state.time + (state.playing ? (Date.now() - state.at) / 1000 : 0);
        function loadVideo(v, autoplay = true) {
            current = v;
            state = { ...state, playing: false, time: 0, duration: 0, at: Date.now(), inList: !!v?.list };
            frame?.remove();
            frame = null;
            if (!v) {
                empty.hidden = false;
                api.storage.delete("last").catch(() => {});
                render();
                return;
            }
            empty.hidden = true;
            const params = new URLSearchParams({ autoplay: autoplay ? "1" : "0", enablejsapi: "1", playsinline: "1", rel: "0", modestbranding: "1",
                controls: "0", iv_load_policy: "3", fs: "0", origin: location.origin });
            if (v.start) params.set("start", String(v.start));
            if (v.list) params.set("list", v.list);
            const path = v.id ? `embed/${v.id}` : "embed/videoseries";
            frame = el("iframe", {
                src: `https://www.youtube.com/${path}?${params}`,
                allow: "autoplay; encrypted-media; picture-in-picture; fullscreen; clipboard-write",
                allowFullscreen: true,
                referrerPolicy: "strict-origin-when-cross-origin",
                title: v.title || "YouTube video",
            });
            frame.addEventListener("load", () => {
                try { frame.contentWindow.postMessage(JSON.stringify({ event: "listening", id: "bt-yt", channel: "widget" }), "*"); } catch {}
            });
            screen.append(frame);
            if (api.settings.rememberLast !== false) api.storage.set("last", { ...v, start: 0 }).catch(() => {});
            render();
        }
        const onMessage = e => {
            if (!frame || e.source !== frame.contentWindow) return;
            let data;
            try { data = typeof e.data === "string" ? JSON.parse(e.data) : e.data; } catch { return; }
            const info = data?.info;
            if (!info || typeof info !== "object") return;
            if (typeof info.playerState === "number") state.playing = info.playerState === 1;
            if (typeof info.currentTime === "number") { state.time = info.currentTime; state.at = Date.now(); }
            if (typeof info.duration === "number" && info.duration > 0) state.duration = info.duration;
            if (typeof info.volume === "number" && !volDragging && Date.now() - volSetAt > 1500) state.volume = info.volume;
            if (typeof info.muted === "boolean" && Date.now() - volSetAt > 1500) state.muted = info.muted;
            if (Array.isArray(info.playlist) && info.playlist.length > 1) state.inList = true;
            const vd = info.videoData;
            if (vd && current) {
                if (vd.title) current.title = vd.title;
                if (vd.author) current.channel = vd.author;
                if (vd.video_id && vd.video_id !== current.id) { current.id = vd.video_id; }
            }
            render();
        };
        window.addEventListener("message", onMessage);
        const togglePlay = () => {
            if (!current) return;
            post(state.playing ? "pauseVideo" : "playVideo");
            state.playing = !state.playing;
            render();
        };

        let searchTimer = null, seq = 0, results = [], selected = 0;
        const rows = (items, emptyText) => {
            list.replaceChildren();
            if (!items.length) { list.append(el("div", { className: "bt-yt-msg", textContent: emptyText })); return; }
            items.forEach((v, i) => {
                const row = el("div", { className: `bt-yt-row${i === selected && view === "search" ? " bt-yt-sel" : ""}`, title: v.title });
                const thumb = el("div", { className: "bt-yt-thumb" });
                thumb.style.backgroundImage = `url("https://i.ytimg.com/vi/${v.id}/mqdefault.jpg")`;
                if (v.duration || v.live) thumb.append(el("span", { className: `bt-yt-dur${v.live ? " bt-yt-live" : ""}`, textContent: v.live ? "LIVE" : v.duration }));
                const text = el("div", { className: "bt-yt-rowtext" });
                text.append(el("div", { className: "bt-yt-rowtitle", textContent: v.title }), el("div", { className: "bt-yt-rowchan", textContent: v.channel }));
                row.append(thumb, text);
                row.onclick = () => {
                    loadVideo({ id: v.id, title: v.title, channel: v.channel });
                    if (view === "search") { input.value = ""; results = []; list.replaceChildren(); }
                };
                list.append(row);
            });
        };
        const isChannelLink = text => /^(https?:\/\/)?(www\.|m\.)?youtube\.com\/(@[\w.-]+|channel\/UC[\w-]{22}|c\/[^/?#]+|user\/[^/?#]+)\/?([?#].*)?$/i.test(String(text).trim());
        const tryLink = text => {
            if (isChannelLink(text)) {
                input.value = "";
                followChannel(String(text).trim());
                return true;
            }
            const link = parseYouTube(text);
            if (!link) return false;
            loadVideo({ ...link, title: "", channel: "" });
            input.value = "";
            results = [];
            list.replaceChildren();
            input.blur();
            return true;
        };
        async function runSearch() {
            const q = input.value.trim();
            const my = ++seq;
            if (!q) { results = []; list.replaceChildren(); return; }
            if (parseYouTube(q) || isChannelLink(q)) return;
            list.replaceChildren(el("div", { className: "bt-yt-msg", textContent: "Searching…" }));
            try {
                const found = await api.youtube.search(q);
                if (my !== seq) return;
                results = found;
                selected = 0;
                rows(results, "No results.");
            } catch (error) {
                if (my !== seq) return;
                list.replaceChildren(el("div", { className: "bt-yt-msg", textContent: `Search failed: ${String(error?.message || error).replace(/^Error invoking remote method '[^']+': (Error: )?/, "")}` }));
            }
        }
        input.addEventListener("input", () => {
            if (view !== "search") setView("search");
            clearTimeout(searchTimer);
            searchTimer = setTimeout(runSearch, 400);
        });
        const onPasteFirst = e => {
            if (e.target !== input) return;
            e.stopImmediatePropagation();
            const text = e.clipboardData?.getData("text") || "";
            if (parseYouTube(text) || isChannelLink(text)) { e.preventDefault(); tryLink(text); }
        };
        window.addEventListener("paste", onPasteFirst, true);
        for (const type of ["keyup", "keypress"]) input.addEventListener(type, e => e.stopPropagation());
        input.addEventListener("keydown", e => {
            e.stopPropagation();
            if (e.key === "Enter") {
                e.preventDefault();
                if (tryLink(input.value)) return;
                if (results[selected]) list.children[selected]?.click();
                else { clearTimeout(searchTimer); runSearch(); }
            } else if (e.key === "Escape") {
                input.value = ""; results = []; list.replaceChildren(); input.blur();
            } else if ((e.key === "ArrowDown" || e.key === "ArrowUp") && results.length) {
                e.preventDefault();
                selected = (selected + (e.key === "ArrowDown" ? 1 : results.length - 1)) % results.length;
                rows(results, "");
            }
        });

        const feedCache = new Map();
        const saveChannels = () => api.storage.set("channels", channels).catch(() => {});
        const msgRow = text => el("div", { className: "bt-yt-msg", textContent: text });
        async function showFeed() {
            for (const [k, b] of tabBtns) b.classList.toggle("bt-yt-on", k === feed || (k === "channels" && feed === "channel"));
            if (!channels.length) {
                list.replaceChildren(msgRow("Follow channels in Be Themer → Plugins → YouTube → Settings (or paste a channel link in the search bar) to see their latest videos here."));
                return;
            }
            if (feed === "channels") {
                list.replaceChildren();
                for (const ch of [...channels].sort((a, b) => a.name.localeCompare(b.name))) {
                    const row = el("div", { className: "bt-yt-row bt-yt-chanrow", title: `Latest from ${ch.name}` });
                    const text = el("div", { className: "bt-yt-rowtext" });
                    text.append(el("div", { className: "bt-yt-rowtitle", textContent: ch.name }));
                    const x = btn("close", `Unfollow ${ch.name}`, () => unfollow(ch.id));
                    row.append(text, x);
                    row.onclick = () => { feed = "channel"; openChannel = ch; showFeed(); };
                    list.append(row);
                }
                return;
            }
            const ids = feed === "channel" && openChannel ? [openChannel.id] : channels.map(c => c.id);
            const key = `${feed}:${ids.join(",")}:${!!api.settings.includeShorts}`;
            const header = feed === "channel" && openChannel ? (() => {
                const back = el("div", { className: "bt-yt-row bt-yt-backrow" });
                back.append(el("span", { innerHTML: ytIcon("back", 14) }), el("span", { textContent: openChannel.name }));
                back.onclick = () => { feed = "channels"; showFeed(); };
                return back;
            })() : null;
            if (feedCache.has(key)) { rows(feedCache.get(key), "No videos."); if (header) list.prepend(header); return; }
            list.replaceChildren(msgRow("Loading…"));
            if (header) list.prepend(header);
            try {
                const items = await api.youtube.channelVideos(ids, !!api.settings.includeShorts);
                feedCache.set(key, items);
                if (view === "library" && `${feed}:${(feed === "channel" && openChannel ? [openChannel.id] : channels.map(c => c.id)).join(",")}:${!!api.settings.includeShorts}` === key) {
                    rows(items, "No videos.");
                    if (header) list.prepend(header);
                }
            } catch (error) {
                list.replaceChildren(msgRow(`Couldn't load videos (${String(error?.message || error).replace(/^Error invoking remote method '[^']+': (Error: )?/, "")}).`));
            }
        }
        async function followChannel(text) {
            if (!text) return api.toast("Paste a channel link or @handle first.");
            api.toast("Looking up the channel…");
            try {
                const ch = await api.youtube.resolveChannel(text);
                if (channels.some(c => c.id === ch.id)) return api.toast(`You already follow ${ch.name}.`);
                channels.push(ch);
                saveChannels();
                feedCache.clear();
                api.toast(`Following ${ch.name}`);
                updateStatus();
                if (view === "library") showFeed();
            } catch (error) {
                api.toast(String(error?.message || error).replace(/^Error invoking remote method '[^']+': (Error: )?/, ""), 6000);
            }
        }
        function unfollow(id) {
            const ch = channels.find(c => c.id === id);
            channels = channels.filter(c => c.id !== id);
            saveChannels();
            feedCache.clear();
            if (ch) api.toast(`Unfollowed ${ch.name}`);
            updateStatus();
            if (view === "library") showFeed();
        }
        function importTakeout() {
            const pick = el("input", { type: "file", accept: ".csv,text/csv" });
            pick.onchange = async () => {
                const file = pick.files?.[0];
                if (!file) return;
                const text = await file.text();
                const found = [];
                for (const line of text.split(/\r?\n/).slice(1)) {
                    const id = (/(UC[\w-]{22})/.exec(line) || [])[1];
                    if (!id) continue;
                    const m = /,(?:"((?:[^"]|"")*)"|([^,]*))\s*$/.exec(line);
                    const name = (m?.[1]?.replace(/""/g, '"') ?? m?.[2] ?? id).trim() || id;
                    found.push({ id, name });
                }
                if (!found.length) return api.toast("That file has no channels in it. Pick subscriptions.csv from your Takeout download.", 6000);
                const known = new Set(channels.map(c => c.id));
                const added = found.filter(c => !known.has(c.id) && known.add(c.id));
                channels.push(...added);
                saveChannels();
                feedCache.clear();
                api.toast(`Imported ${added.length} channel${added.length === 1 ? "" : "s"}${found.length > added.length ? ` (${found.length - added.length} already followed)` : ""}.`);
                updateStatus();
                if (view === "library") showFeed();
            };
            pick.click();
        }
        function setView(v) {
            view = v;
            libraryBtn.classList.toggle("bt-yt-on", v === "library");
            tabs.hidden = v !== "library";
            if (v === "library") { if (feed === "channel") feed = "channels"; showFeed(); }
            else rows(results, "");
            if (v === "search" && !results.length) list.replaceChildren();
        }
        tabs.hidden = true;

        function setCollapsed(on, save = true) {
            collapsed = !!on;
            root.classList.toggle("bt-yt-collapsed", collapsed);
            chevronBtn.title = collapsed ? "Expand" : "Collapse";
            chevronBtn.setAttribute("aria-expanded", String(!collapsed));
            if (save) api.storage.set("collapsed", collapsed).catch(() => {});
        }

        function render() {
            root.classList.toggle("bt-yt-audio", api.settings.showVideo === false);
            const t = current?.title || (current ? "Loading…" : "YouTube");
            title.replaceChildren(document.createTextNode(t));
            if (current?.channel) title.append(el("small", { textContent: current.channel }));
            title.title = current?.title || "";
            miniBtn.innerHTML = ytIcon(state.playing ? "pause" : "play", 13);
            miniBtn.title = state.playing ? "Pause" : "Play";
            miniBtn.hidden = !current;
            openBtn.hidden = closeBtn.hidden = !current;
            libraryBtn.hidden = false;
            renderControls();
        }
        const tick = setInterval(() => {
            const pct = state.duration ? Math.min(100, (liveTime() / state.duration) * 100) : 0;
            progressFill.style.width = `${pct}%`;
            if (!seekDragging) {
                seekBar.set(pct / 100);
                timeText.textContent = `${fmt(liveTime())} / ${fmt(state.duration)}`;
            }
        }, 500);

        function updateStatus() {
            api.setSetting("followStatus", channels.length
                ? `Following ${channels.length} channel${channels.length === 1 ? "" : "s"}: ${channels.slice(0, 4).map(c => c.name).join(", ")}${channels.length > 4 ? ", …" : ""}`
                : "Not following any channels yet");
            render();
        }
        this.follow = async () => {
            const text = String(api.settings.followInput || "").trim();
            await followChannel(text);
            api.setSetting("followInput", "");
        };
        this.importTakeout = importTakeout;
        this.unfollowAll = () => {
            if (!channels.length) return;
            channels = [];
            saveChannels();
            feedCache.clear();
            api.toast("Unfollowed every channel.");
            updateStatus();
            if (view === "library") showFeed();
        };
        this.reloadFeed = () => { feedCache.clear(); if (view === "library") showFeed(); };
        this.refresh = () => render();

        const mount = panels => {
            if (stopped || !panels) return;
            const sp = panels.querySelector(":scope > .bt-sp");
            if (sp ? sp.nextElementSibling === root : panels.firstElementChild === root) return;
            if (sp) sp.after(root);
            else panels.prepend(root);
        };
        api.observe('section[class*="panels_"]', mount);
        const mountTimer = setInterval(() => mount(document.querySelector('section[class*="panels_"]')), 2000);

        api.storage.get("collapsed").then(v => { if (v) setCollapsed(true, false); }).catch(() => {});
        if (api.settings.rememberLast !== false) {
            api.storage.get("last").then(v => { if (v && (v.id || v.list) && !current) loadVideo(v, false); }).catch(() => {});
        }
        api.storage.get("channels").then(v => {
            if (Array.isArray(v)) channels = v.filter(c => c && /^UC[\w-]{22}$/.test(c.id));
            updateStatus();
        }).catch(() => updateStatus());
        render();

        api.onDispose(() => {
            stopped = true;
            clearInterval(tick);
            clearInterval(mountTimer);
            clearTimeout(searchTimer);
            window.removeEventListener("message", onMessage);
            window.removeEventListener("paste", onPasteFirst, true);
            frame?.remove();
            root.remove();
            delete this.follow;
            delete this.importTakeout;
            delete this.unfollowAll;
            delete this.reloadFeed;
            delete this.refresh;
        });
    },
    onSettingChange(key) {
        if (key === "followBtn") this.follow?.();
        else if (key === "importBtn") this.importTakeout?.();
        else if (key === "unfollowAllBtn") this.unfollowAll?.();
        else if (key === "includeShorts") this.reloadFeed?.();
        else if (key === "showVideo") this.refresh?.();
    },
});
